func retryWithBackoff(fn func() error, maxRetries int) error {
    var lastErr error
    for attempt := 1; attempt <= maxRetries; attempt++ {
        if err := fn(); err == nil {
            return nil
        } else {
            lastErr = err
        }
    }
    return fmt.Errorf("failed after %d retries: %w", maxRetries, lastErr)
