-- Check 3.3: Conversion Accuracy Sample (Spot-Check)
-- Compare DECIMAL * 100 vs stored BIGINT for rounding differences
WITH conversion_sample AS (
    SELECT 
        oim.old_order_id AS legacy_order_id,
        o.id AS new_order_id,
        ol.amount AS legacy_amount,
        o.amount_cents AS migrated_cents,
        CAST(ROUND(ol.amount * 100) AS BIGINT) AS expected_cents,
        ABS(CAST(ROUND(ol.amount * 100) AS BIGINT) - o.amount_cents) AS rounding_diff,
        CASE 
            WHEN ABS(CAST(ROUND(ol.amount * 100) AS BIGINT) - o.amount_cents) > 1 THEN 'WARN'
            ELSE 'OK'
        END AS accuracy_status
    FROM orders_legacy ol
    INNER JOIN id_mapping_orders oim ON ol.id = oim.legacy_order_id
    INNER JOIN orders o ON oim.new_order_id = o.id
)
SELECT 
    'VALIDATION 3.3: Amount Conversion Accuracy (Sample)' AS check_name,
    COUNT(*) AS sample_size,
    COUNT(CASE WHEN accuracy_status = 'OK' THEN 1 END) AS accurate_count,
    COUNT(CASE WHEN accuracy_status = 'WARN' THEN 1 END) AS rounding_issues,
    MAX(rounding_diff) AS max_rounding_diff_cents,
    ROUND(COUNT(CASE WHEN accuracy_status = 'OK' THEN 1 END) * 100.0 / COUNT(*), 2) AS accuracy_percentage
FROM conversion_sample;

-- Check 3.4: Cumulative Amount Validation (Sum Check)
DO $$
DECLARE
    v_legacy_sum DECIMAL;
    v_new_sum BIGINT;
    v_legacy_sum_cents BIGINT;
    v_difference BIGINT;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_legacy_sum FROM orders_legacy;
    SELECT COALESCE(SUM(amount_cents), 0) INTO v_new_sum FROM orders;

    v_legacy_sum_cents := CAST(ROUND(v_legacy_sum * 100) AS BIGINT);
    v_difference := ABS(v_legacy_sum_cents - v_new_sum);

    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'VALIDATION 3.4: Cumulative Amount Sum Check';
    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'Legacy total amount: %', v_legacy_sum;
    RAISE NOTICE 'Legacy total (cents): %', v_legacy_sum_cents;
    RAISE NOTICE 'New total amount_cents: %', v_new_sum;
    RAISE NOTICE 'Total difference (cents): %', v_difference;

    -- Allow max 10 cents difference due to rounding across all orders
    IF v_difference <= 10 THEN
        RAISE NOTICE '✅ PASS: Cumulative amount within acceptable tolerance (±10 cents)';
    ELSE
        RAISE WARNING '⚠️  WARNING: Significant rounding variance detected (% cents)', v_difference;
    END IF;
END $$;

-- Check 3.5: Detailed Rounding Analysis
WITH rounding_analysis AS (
    SELECT 
        ol.amount,
        o.amount_cents,
        CAST(ROUND(ol.amount * 100) AS BIGINT) AS expected_cents,
        ABS(CAST(ROUND(ol.amount * 100) AS BIGINT) - o.amount_cents) AS diff,
        CASE 
            WHEN ol.amount * 100 = ROUND(ol.amount * 100) THEN 'No Rounding'
            WHEN ABS(CAST(ROUND(ol.amount * 100) AS BIGINT) - CAST(ol.amount * 100 AS BIGINT)) = 0 THEN 'Already Rounded'
            ELSE 'Rounding Applied'
        END AS rounding_category
    FROM orders_legacy ol
    INNER JOIN id_mapping_orders oim ON ol.id = oim.legacy_order_id
    INNER JOIN orders o ON oim.new_order_id = o.id
)
SELECT 
    'VALIDATION 3.5: Rounding Distribution' AS check_type,
    rounding_category,
    COUNT(*) AS count,
    COUNT(*) * 100.0 / (SELECT COUNT(*) FROM rounding_analysis) AS percentage,
    MIN(amount) AS min_amount,
    MAX(amount) AS max_amount
FROM rounding_analysis
GROUP BY rounding_category
ORDER BY count DESC;
```

