BEGIN
    SELECT COUNT(*) INTO v_tables FROM information_schema.tables 
    WHERE table_name IN ('products','accounts','account_roles','orders','order_events','audit_log')
    AND table_schema = 'public';

    SELECT COUNT(*) INTO v_mappings FROM information_schema.tables 
    WHERE table_name IN ('id_mapping_users','id_mapping_orders')
    AND table_schema = 'public';

    SELECT COUNT(*) INTO v_triggers FROM information_schema.triggers 
    WHERE trigger_name = 'orders_dual_write';

    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'PHASE 1: COMPLETION CHECKPOINT';
    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'New schema tables created: %/6', v_tables;
    RAISE NOTICE 'Mapping tables created: %/2', v_mappings;
    RAISE NOTICE 'Dual-write triggers: %/1', v_triggers;

    IF v_tables = 6 AND v_mappings = 2 AND v_triggers = 1 THEN
        RAISE NOTICE '✅ PHASE 1 COMPLETE: All infrastructure ready';
    ELSE
        RAISE EXCEPTION 'PHASE 1 FAILED: Missing components (tables=%,mappings=%,triggers=%)', v_tables, v_mappings, v_triggers;
    END IF;
END $$;
```

