## PHASE 2: BACKFILL MIGRATION (Read-Only Legacy)

### 2.1: Migrate Products

```sql
DO $$
DECLARE
    v_inserted INT;
    v_duplicates INT;
BEGIN
    INSERT INTO products (id, name, category, created_at, updated_at)
    SELECT 
        gen_random_uuid(),
        TRIM(product_name),
        NULL,
        NOW(),
        NOW()
    FROM (
        SELECT DISTINCT product_name FROM orders_legacy WHERE product_name IS NOT NULL
    ) src
    ON CONFLICT (name) DO NOTHING;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    SELECT COUNT(DISTINCT product_name) INTO v_duplicates 
    FROM orders_legacy WHERE product_name IS NOT NULL;

    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'PHASE 2.1: Product Migration';
    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'Unique products in legacy: %', v_duplicates;
    RAISE NOTICE 'Products inserted into new: %', v_inserted;
    RAISE NOTICE '✅ Product migration complete';
END $$;
```

### 2.2: Migrate Users → Accounts

```sql
DO $$
DECLARE
    v_inserted INT;
    v_total_legacy INT;
    v_invalid_emails INT;
BEGIN
    -- Check for data quality issues first
    SELECT COUNT(*) INTO v_total_legacy FROM users_legacy;
    SELECT COUNT(*) INTO v_invalid_emails FROM users_legacy WHERE email IS NULL OR TRIM(email) = '';

    IF v_invalid_emails > 0 THEN
        RAISE WARNING 'WARNING: % users with NULL/empty email. These will be skipped.', v_invalid_emails;
    END IF;

    INSERT INTO accounts (id, display_name, email, created_at, updated_at)
    SELECT 
        gen_random_uuid(),
        COALESCE(TRIM(name), 'Unknown'),
        LOWER(TRIM(email)),
        COALESCE(created_at, NOW()),
        COALESCE(updated_at, created_at, NOW())
    FROM users_legacy
    WHERE email IS NOT NULL AND TRIM(email) != ''
    ON CONFLICT (email) DO NOTHING;

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    -- Populate mapping
    INSERT INTO id_mapping_users (legacy_user_id, new_account_id)
    SELECT ul.id, a.id
    FROM users_legacy ul
    INNER JOIN accounts a ON LOWER(TRIM(ul.email)) = LOWER(TRIM(a.email))
    ON CONFLICT DO NOTHING;

    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'PHASE 2.2: Users → Accounts Migration';
    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'Legacy users total: %', v_total_legacy;
    RAISE NOTICE 'Accounts inserted: %', v_inserted;
    RAISE NOTICE 'Accounts with invalid email (skipped): %', v_invalid_emails;
    RAISE NOTICE '✅ Account migration complete';
END $$;
```

