### 2.4: Migrate Orders with amount_cents Validation

```sql
DO $$
DECLARE
    v_inserted INT;
    v_legacy_orders INT;
    v_unmapped_users INT;
    v_null_amounts INT;
BEGIN
    SELECT COUNT(*) INTO v_legacy_orders FROM orders_legacy;
    SELECT COUNT(*) INTO v_unmapped_users 
    FROM orders_legacy ol 
    LEFT JOIN id_mapping_users uim ON ol.user_id = uim.legacy_user_id
    WHERE uim.new_account_id IS NULL;
    SELECT COUNT(*) INTO v_null_amounts 
    FROM orders_legacy WHERE amount IS NULL OR amount = 0;

    IF v_unmapped_users > 0 THEN
        RAISE WARNING 'WARNING: % orders have unmapped users (will be skipped)', v_unmapped_users;
    END IF;

    IF v_null_amounts > 0 THEN
        RAISE WARNING 'WARNING: % orders have NULL/zero amounts (will be migrated as 0 cents)', v_null_amounts;
    END IF;

    INSERT INTO orders (id, account_id, product_id, amount_cents, currency, status, created_at, updated_at)
    SELECT 
        gen_random_uuid(),
        uim.new_account_id,
        p.id,
        CAST(ROUND(COALESCE(ol.amount, 0) * 100) AS BIGINT),
        COALESCE(TRIM(ol.currency), 'USD'),
        CASE WHEN ol.status IN ('pending','paid','shipped','delivered','cancelled') 
             THEN ol.status ELSE 'pending' END,
        COALESCE(ol.created_at, NOW()),
        COALESCE(ol.updated_at, ol.created_at, NOW())
    FROM orders_legacy ol
    INNER JOIN id_mapping_users uim ON ol.user_id = uim.legacy_user_id
    LEFT JOIN products p ON TRIM(LOWER(COALESCE(ol.product_name,''))) = TRIM(LOWER(p.name))
    WHERE ol.id IS NOT NULL;  -- Ensure no NULL IDs

    GET DIAGNOSTICS v_inserted = ROW_COUNT;

    -- Populate order mapping (best-effort based on account_id + amount_cents + created_at match)
    INSERT INTO id_mapping_orders (legacy_order_id, new_order_id)
    SELECT ol.id, o.id
    FROM orders_legacy ol
    INNER JOIN id_mapping_users uim ON ol.user_id = uim.legacy_user_id
    INNER JOIN orders o ON o.account_id = uim.new_account_id
        AND o.created_at = COALESCE(ol.created_at, NOW())
        AND o.amount_cents = CAST(ROUND(COALESCE(ol.amount, 0) * 100) AS BIGINT)
    ON CONFLICT DO NOTHING;

    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'PHASE 2.4: Orders Migration';
    RAISE NOTICE '═══════════════════════════════════════════════';
    RAISE NOTICE 'Legacy orders: %', v_legacy_orders;
    RAISE NOTICE 'Orders inserted: %', v_inserted;
    RAISE NOTICE 'Orders skipped (unmapped users): %', v_unmapped_users;
    RAISE NOTICE '✅ Orders migration complete';
END $$;
```

### 2.5: Validation Gates (ALL MUST PASS)

```sql
-- GATE 1: Foreign Key Integrity
DO $$
DECLARE v_orphans INT;
BEGIN
    SELECT COUNT(*) INTO v_orphans FROM orders 
    WHERE account_id NOT IN (SELECT id FROM accounts);

    IF v_orphans > 0 THEN 
        RAISE EXCEPTION '❌ GATE 1 FAILED: % orphaned orders', v_orphans; 
    END IF;
    RAISE NOTICE '✅ GATE 1 PASS: FK integrity verified (0 orphaned orders)';
END $$;

-- GATE 2: amount_cents Validation (NOT NULL + >= 0)
DO $$
DECLARE v_nulls INT; v_negative INT;
BEGIN
    SELECT COUNT(*) INTO v_nulls FROM orders WHERE amount_cents IS NULL;
    SELECT COUNT(*) INTO v_negative FROM orders WHERE amount_cents < 0;
    IF v_nulls > 0 OR v_negative > 0 THEN 
        RAISE EXCEPTION '❌ GATE 2 FAILED: nulls=%, negative=%', v_nulls, v_negative; 
    END IF;
    RAISE NOTICE '✅ GATE 2 PASS: amount_cents valid (% orders checked)', (SELECT COUNT(*) FROM orders);
END $$;

-- GATE 3: Data Completeness (Row Count Parity)
DO $$
DECLARE v_legacy_users INT; v_legacy_orders INT; v_new_accounts INT; v_new_orders INT;
BEGIN
    SELECT COUNT(*) INTO v_legacy_users FROM users_legacy;
    SELECT COUNT(*) INTO v_legacy_orders FROM orders_legacy;
    SELECT COUNT(*) INTO v_new_accounts FROM accounts;
    SELECT COUNT(*) INTO v_new_orders FROM orders;

    IF v_legacy_users != v_new_accounts THEN
        RAISE WARNING 'WARNING: User count mismatch (legacy=%,new=%)', v_legacy_users, v_new_accounts;
    END IF;
    IF v_legacy_orders != v_new_orders THEN
        RAISE WARNING 'WARNING: Order count mismatch (legacy=%,new=%)', v_legacy_orders, v_new_orders;
    END IF;

    RAISE NOTICE '✅ GATE 3 PASS: Data completeness verified';
    RAISE NOTICE '  Legacy users: %, New accounts: %', v_legacy_users, v_new_accounts;
    RAISE NOTICE '  Legacy orders: %, New orders: %', v_legacy_orders, v_new_orders;
END $$;

-- GATE 4: Email Uniqueness in Accounts
DO $$
DECLARE v_duplicates INT;
BEGIN
    SELECT COUNT(*) INTO v_duplicates FROM (
        SELECT email, COUNT(*) FROM accounts GROUP BY email HAVING COUNT(*) > 1
    ) x;

    IF v_duplicates > 0 THEN 
        RAISE EXCEPTION '❌ GATE 4 FAILED: % duplicate emails found', v_duplicates; 
    END IF;
    RAISE NOTICE '✅ GATE 4 PASS: Email uniqueness verified';
END $$;

-- GATE 5: Status Enum Validity
DO $$
DECLARE v_invalid INT;
BEGIN
    SELECT COUNT(*) INTO v_invalid FROM orders 
    WHERE status NOT IN ('pending','paid','shipped','delivered','cancelled');

    IF v_invalid > 0 THEN 
        RAISE EXCEPTION '❌ GATE 5 FAILED: % orders with invalid status', v_invalid; 
    END IF;
    RAISE NOTICE '✅ GATE 5 PASS: Status enum valid';
END $$;

-- GATE 6: Cumulative Amount Validation (Sum Check)
DO $$
DECLARE
    v_legacy_sum DECIMAL;
    v_new_sum BIGINT;
    v_legacy_sum_cents BIGINT;
    v_difference BIGINT;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO v_legacy_sum FROM orders_legacy;
    SELECT COALESCE(SUM(amount_cents), 0) INTO v_new_sum FROM orders;

    v_legacy_sum_cents := CAST(ROUND(v_legacy_sum * 100) AS BIGINT);
    v_difference := ABS(v_legacy_sum_cents - v_new_sum);

    -- Allow max 10 cents difference due to rounding across all orders
    IF v_difference > 10 THEN
        RAISE WARNING '⚠️  GATE 6 WARNING: Rounding variance = % cents (tolerance: 10)', v_difference;
    END IF;

    RAISE NOTICE '✅ GATE 6 PASS: Amount sum validated';
    RAISE NOTICE '  Legacy total: %, New total: % cents, Difference: % cents', 
        v_legacy_sum, v_new_sum, v_difference;
END $$;

-- GATE 7: Manual Spot-Check (Sample validation)
RAISE NOTICE '═══════════════════════════════════════════════';
RAISE NOTICE 'GATE 7: MANUAL SPOT-CHECK REQUIRED';
RAISE NOTICE '═══════════════════════════════════════════════';

SELECT 
    'Sample 10 Orders' as analysis,
    COUNT(*) as count,
    COUNT(DISTINCT account_id) as unique_accounts,
    MIN(amount_cents) as min_amount,
    MAX(amount_cents) as max_amount,
    AVG(amount_cents) as avg_amount,
    COUNT(CASE WHEN product_id IS NULL THEN 1 END) as null_products
FROM (SELECT * FROM orders LIMIT 10) x;

RAISE NOTICE 'GATE 7: ⚠️  MANUAL REVIEW REQUIRED - Examine sample data above';
RAISE NOTICE 'Action: DBA must confirm sample data quality before approval to proceed';
