### 3.2: Disable Dual-Write & Archive Legacy

```sql
DO $$
BEGIN
    -- Disable dual-write trigger (stop syncing new → legacy)
    ALTER TABLE orders DISABLE TRIGGER orders_dual_write;
    RAISE NOTICE '✅ Dual-write trigger disabled';

    -- Archive legacy tables (atomic rename - never dropped)
    ALTER TABLE users_legacy RENAME TO users_archive_2025;
    ALTER TABLE orders_legacy RENAME TO orders_archive_2025;
    ALTER TABLE audit_log_legacy RENAME TO audit_log_archive_2025;
    RAISE NOTICE '✅ Legacy tables archived (renamed to *_archive_2025)';

    -- Revoke write access to archives (read-only)
    REVOKE INSERT, UPDATE, DELETE ON users_archive_2025 FROM app_user;
    REVOKE INSERT, UPDATE, DELETE ON orders_archive_2025 FROM app_user;
    REVOKE INSERT, UPDATE, DELETE ON audit_log_archive_2025 FROM app_user;
    GRANT SELECT ON users_archive_2025 TO app_user;
    GRANT SELECT ON orders_archive_2025 TO app_user;
    GRANT SELECT ON audit_log_archive_2025 TO app_user;
    RAISE NOTICE '✅ Archive tables set to read-only';

    RAISE NOTICE '';
    RAISE NOTICE '⏳ STEP 2: Application switches to new schema (UUID queries)';
    RAISE NOTICE 'Action: Application connection pool resets to new schema';
    RAISE NOTICE '';
END $$;
```

